import React, { useEffect, useRef } from 'react';
import { Button } from 'primereact/button';
import { Messages } from 'primereact/messages';

export default function Dynamic() {
    const msgs = useRef(null);

    const addMessages = () => {
        msgs.current.show([
            { className: 'success', summary: 'Success', detail: 'Message Content', sticky: true, closable: false },
            { className: 'info', summary: 'Info', detail: 'Message Content', sticky: true, closable: false },
            { className: 'warn', summary: 'Warning', detail: 'Message Content', sticky: true, closable: false },
            { className: 'error', summary: 'Error', detail: 'Message Content', sticky: true, closable: false }
        ]);
    };

    const clearMessages = () => {
        msgs.current.clear();
    };

    return (
        <div className="card">
            <Button type="button" onClick={addMessages} label="Show" className="mgr8" />
            <Button type="button" onClick={clearMessages} label="Clear" className="mgr8 secondary" />

            <Messages ref={msgs} />
        </div>
    )
}